# A(1): arithmetic of Gbar = Cl^+_{m}(K) / <[-1]>, m = conductor modulus of the E-class (rational part), K = Q(sqrt(s^2-2s)).
#   R = image of rational ideal classes; sigma acts as -1 on Gbar/R (sigma(g) g = [N g] in R).
#   Reports |Gbar|, |Gbar^sigma| (via |(1-sigma)Gbar|), |Rbar|, structure and exponent of Gbar/Rbar, h+, genus number 2^{t-1}.
import cypari2, json, sys, math
pari = cypari2.Pari(); pari.allocatemem(4*10**9)
from uL_rayclass_exact import sqfree
def index_of(gens_cols, cyc):
    # index in Z^r/diag(cyc) of the subgroup generated by the columns
    r = len(cyc)
    if r == 0: return 1, 1
    M = pari.matconcat([pari.matrix(r, len(gens_cols), [x for col in zip(*gens_cols) for x in col]) if gens_cols else pari.matrix(r, 0), pari.matdiagonal(cyc)])
    H = pari.mathnf(M); sub = int(pari.matdet(H))
    return math.prod(cyc)//sub, sub          # (|subgroup|, index)
def run(s, m):
    D0, c = sqfree(s*s - 2*s); K = pari(f'bnfinit(x^2-{D0},1)')
    bnr = pari.bnrinit(K, pari(f'[{m},[1,1]]'), 1); cyc = [int(z) for z in pari('(b)->b.cyc')(bnr)]; r = len(cyc)
    gens = pari('(b)->b.gen')(bnr)
    cls = lambda I: [int(z) for z in pari.bnrisprincipal(bnr, I, 0)]
    j = cls(pari(10**6*m - 1)) if m > 1 else [0]*r
    sig = [z for z in pari.nfgaloisconj(K) if str(z) != 'x'][0]
    Sg = [cls(pari.nfgaloisapply(K, sig, gens[i])) for i in range(r)]
    # quotient by <j>: work with subgroup lattice  J = <j> ; (1-sigma)G + J ; R + J
    Jsz, _ = index_of([j], cyc)
    one_minus = [[(int(i == k) - Sg[i][k]) for k in range(r)] for i in range(r)]
    HJ, _ = index_of(one_minus + [j], cyc)
    Rg = []; p = 2
    while p < 400:
        if m % p and D0 % p and (s*s - 2*s) % p: Rg.append(cls(pari(p)))
        p = int(pari.nextprime(p+1))
    RJ, _ = index_of(Rg + [j], cyc)
    G = math.prod(cyc); Gbar = G // Jsz; Hbar = HJ // Jsz; Rbar = RJ // Jsz
    # structure of Gbar/Rbar
    Mq = pari.matconcat([pari.matrix(r, len(Rg)+1, [x for col in zip(*(Rg+[j])) for x in col]), pari.matdiagonal(cyc)])
    snf = [int(z) for z in pari.matsnf(pari.mathnf(Mq)) if int(z) > 1]
    ram = len(pari.factor(int(pari('(K)->K.disc')(K)))[0])
    return dict(s=s, m=m, D0=D0, hplus=int(pari('(K)->K.clgp.no')(K)), genus_number=2**(ram-1), cyc=cyc, Gbar=Gbar, Hbar=Hbar, Gbar_sigma=Gbar//Hbar,
                Rbar=Rbar, Gbar_mod_R_snf=snf, exp_Gbar_mod_R=(max(snf) if snf else 1), phi_m=int(pari.eulerphi(m)))
if __name__ == "__main__":
    pairs = [tuple(map(int, a.split(':'))) for a in sys.argv[1:]]
    out = []
    for s, m in pairs:
        o = run(s, m); print(json.dumps(o), flush=True); out.append(o)
    json.dump(out, open('gbar_arith_%d_%d.json' % (pairs[0][0], pairs[-1][0]), 'w'), indent=1)
